<script setup>
defineProps({ snapshots: { type: Array, default: () => [] }, enabled: { type: Object, default: () => ({}) }, t: Object, locale: String });
const fields = [['temperature', 'temperature', '°C'], ['apparent_temperature', 'apparentTemperature', '°C'], ['relative_humidity', 'relativeHumidity', '%'], ['precipitation', 'precipitation', ' mm'], ['pressure', 'pressure', ' hPa'], ['wind_speed', 'windSpeed', ' km/h']];
function formattedTime(timestamp, locale) { return new Intl.DateTimeFormat(locale, { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }).format(new Date(timestamp)); }
</script>
<template><div class="forecast-table-wrap"><table class="forecast-table"><thead><tr><th>{{ t.time }}</th><th v-for="([key, label]) in fields.filter(([key]) => enabled[key])" :key="key">{{ t[label] }}</th></tr></thead><tbody><tr v-for="snapshot in snapshots" :key="snapshot.timestamp"><th scope="row">{{ formattedTime(snapshot.timestamp, locale) }}</th><td v-for="([key, , unit]) in fields.filter(([key]) => enabled[key])" :key="key">{{ snapshot[key] ?? '—' }}{{ snapshot[key] !== null && snapshot[key] !== undefined ? unit : '' }}</td></tr></tbody></table><p v-if="!snapshots.length" class="empty-table">{{ t.noForecast }}</p></div></template>